s($,"cAw","c84",()=>A.a([A.be("\uc790\uc0b4|\uc790\ud574|\uc8fd\uace0\\s*\uc2f6|\uc8fd\uc5b4\\s*\ubc84\ub9ac\uace0|\uc8fd\uc5b4\ubc84\ub9ac\uace0|\ubaa9\uc228\uc744?\\s*\ub04a|\uc2a4\uc2a4\ub85c\\s*\ubaa9\uc228|\uc190\ubaa9\uc744?\\s*(\uae0b|\uadf8)|\uc0ac\ub77c\uc9c0\uace0\\s*\uc2f6",!0,!1,!1,!1),A.be("\uc0b4\uae30\\s*\uc2eb|\uc0b4\uace0\\s*\uc2f6\uc9c0\\s*\uc54a|\uc5c6\uc5b4\uc9c0\uace0\\s*\uc2f6|\uc8fd\uc5b4\\s*\ubc84\ub838\uc73c\uba74|\uc8fd\uc5c8\uc73c\uba74\\s*(\uc88b\uaca0|\uc2f6)",!0,!1,!1,!1),A.be("\u81ea\u6bba|\u81ea\u5bb3|\u81ea\u50b7|\u6b7b\u306b\u305f\u3044|\u3057\u306b\u305f\u3044|\u6b7b\u3093\u3067\u3057\u307e\u3044\u305f\u3044|\u6d88\u3048\u305f\u3044|\u304d\u3048\u305f\u3044|\u30ea\u30b9\u30c8\u30ab\u30c3\u30c8|\u9996\u3092\u540a",!0,!1,!1,!1),A.be("\u751f\u304d\u3066\u3044\u305f\u304f\u306a\u3044|\u751f\u304d\u305f\u304f\u306a\u3044|\u751f\u304d\u308b\u306e\u304c(\u3064\u3089\u3044|\u82e6\u3057\u3044)|\u3044\u306a\u304f\u306a\u308a\u305f\u3044|\u6d88\u3048\u3066\u3057\u307e\u3044\u305f\u3044|\u6b7b\u306e\u3046\u3068",!0,!1,!1,!1),A.be("suicid|kill myself|want to die|self[- ]?harm|end my life",!1,!1,!1,!1),A.be("don'?t want to (live|be alive)|hurt myself|cut myself",!1,!1,!1,!1)],t._t))
